import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        int n = Integer.parseInt(parts[0]);
        long tmp = Long.parseLong(parts[1]);
        if(n <= tmp) {
            System.out.println(0);
            return;
        }
        int k = (int)tmp;
        long[] fact = new long[400001];
        long[] invFact = new long[400001];
        precomputeFactorials(fact, invFact, 400000);
        long totalComb = nCr(n, n - k, fact, invFact);
        long answer = 0;
        int sign = 1;
        for(int i = n - k; i >= 1; i--) {
            long comb = nCr(n - k, i, fact, invFact);
            long val = pow(i, n);
            answer = (answer + sign * comb * val) % MOD;
            sign *= -1;
        }
        answer = (answer * totalComb) % MOD;
        if(k != 0) answer = (answer * 2) % MOD;
        System.out.println((answer + MOD) % MOD);
    }

    static void precomputeFactorials(long[] fact, long[] invFact, int n) {
        fact[0] = 1;
        for(int i=1;i<=n;i++) {
            fact[i] = (fact[i-1] * i) % MOD;
        }
        invFact[n] = pow(fact[n], MOD - 2);
        for(int i=n-1;i>=0;i--) {
            invFact[i] = (invFact[i+1] * (i+1)) % MOD;
        }
    }

    static long nCr(int n, int r, long[] fact, long[] invFact) {
        if(n<r) return 0;
        return (((fact[n] * invFact[r]) % MOD) * invFact[n - r]) % MOD;
    }

    static long pow(long base, int exp) {
        long result = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }
}
